import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./lock.css";

export function AnimatedLockIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="lock" {...props}>
      <path data-part="shackle" d="M8 10.5V7.75a4 4 0 0 1 8 0v2.75" />
      <rect data-part="body" x="4.75" y="10.5" width="14.5" height="10.5" rx="2.5" />
      <path data-part="keyhole" d="M12 14.75v2" />
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="lock"] {
    & [data-part="shackle"] {
      --icon-y: -1.5px;
      animation-name: icon-nudge;
    }

    & [data-part="keyhole"] {
      --icon-pulse: scaleY(0.6);
      --icon-delay: 120ms;
      transform-origin: 12px 15.75px;
      animation-name: icon-pulse;
    }
  }
}
